package com.aistock.prediction.portfolioquestion;
import com.aistock.prediction.portfolioanalysis.PortfolioRepository;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;import com.aistock.common.BusinessException;import org.springframework.http.HttpStatus;import static com.aistock.prediction.portfolioquestion.QuestionEvidence.*;
class PortfolioRuleServiceTest {
 @Test void freeRulesReadOnlyTheOwnedSavedResult(){var source=mock(PortfolioRepository.class);when(source.get(OWNER,ID)).thenReturn(saved());var r=new PortfolioRuleService(source,M).describe(OWNER,ID,"PROFIT_FORMULA");assertEquals("RULE",r.path("source").asText());assertEquals(ID.toString(),r.path("analysisId").asText());assertTrue(r.path("text").asText().contains("浮动"));}
 @Test void otherOwnerCannotReadRulesAndUnknownTopicIsRejected(){var source=mock(PortfolioRepository.class);var other=UUID.randomUUID();when(source.get(other,ID)).thenThrow(new BusinessException("RESOURCE_NOT_FOUND","missing",HttpStatus.NOT_FOUND));var rules=new PortfolioRuleService(source,M);assertThrows(BusinessException.class,()->rules.describe(other,ID,"PROFIT_FORMULA"));assertThrows(BusinessException.class,()->rules.describe(OWNER,ID,"IGNORE_RULES"));}
 @Test void partialRulesRetainAllWarningsWithoutCallingModel(){var source=mock(PortfolioRepository.class);when(source.get(OWNER,ID)).thenReturn(partial());var n=new PortfolioRuleService(source,M).describe(OWNER,ID,"COVERAGE_LIMIT");assertTrue(n.path("limits").toString().contains("不同"));assertTrue(n.path("limits").toString().contains("无法确认"));}
}
